package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;

/** Arquivos em worker, confirmacao de descarte e recuperacao explicita de backup. */
final class FileTools {
    final WorldStudio ui;Path file;WorldDocument saved;boolean busy;
    FileTools(WorldStudio ui){this.ui=ui;ui.action("Arquivo","Novo mapa",()->confirm(this::create));ui.action("Arquivo","Abrir",()->confirm(()->open(false)));ui.action("Arquivo","Salvar rascunho",()->save(false,()->{}));ui.action("Arquivo","Salvar rascunho como",()->save(true,()->{}));ui.action("Arquivo","Recuperar backup",()->confirm(()->open(true)));ui.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);ui.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(!busy)confirm(ui::dispose);}});saved=ui.document;}
    void confirm(Runnable action){if(busy||ui.liveTools!=null&&!ui.liveTools.confirmDiscard())return;if(ui.document.equals(saved)){action.run();return;}int result=JOptionPane.showConfirmDialog(ui,ui.inGameEditor==null?"Salvar rascunho local antes de continuar? (nao aplica ao jogo)":"Salvar o mapa em disco antes de trocar? As edicoes aceitas ja estao na partida.","Rascunho nao salvo",JOptionPane.YES_NO_CANCEL_OPTION);if(result==JOptionPane.YES_OPTION)save(false,action);else if(result==JOptionPane.NO_OPTION)action.run();}
    Path choose(boolean save){JFileChooser chooser=new JFileChooser(file==null?ui.project.resolve("studio-projects").toFile():file.getParent().toFile());chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Mapa World Studio (*.sgmap)","sgmap","bak"));if(file!=null)chooser.setSelectedFile(file.toFile());int choice=save?chooser.showSaveDialog(ui):chooser.showOpenDialog(ui);if(choice!=JFileChooser.APPROVE_OPTION)return null;Path path=chooser.getSelectedFile().toPath().toAbsolutePath();if(save&&!path.toString().endsWith(".sgmap"))path=Path.of(path+".sgmap");return path;}
    void save(boolean as,Runnable after){if(busy)return;Path target=as||file==null?choose(true):file;if(target==null)return;var snapshot=ui.document;busy=true;ui.setEnabled(false);new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{DocumentStore.save(target,snapshot);return null;}protected void done(){busy=false;ui.setEnabled(true);try{get();file=target;saved=snapshot;ui.knownMaps.put(snapshot.id(),snapshot);ui.status.setText("Salvo: "+target+" | backup .bak quando houver versao anterior");saveCategories();after.run();}catch(Exception error){ui.error(error);}}}.execute();}
    void open(boolean backup){if(busy)return;Path selected=choose(false);if(selected==null)return;load(backup&&!selected.toString().endsWith(".bak")?Path.of(selected+".bak"):selected,backup);}
    void load(Path target,boolean backup){if(busy)return;ui.knownMaps.put(ui.document.id(),ui.document);busy=true;ui.setEnabled(false);new SwingWorker<WorldDocument,Void>(){final Map<String,WorldDocument> known=new LinkedHashMap<>();final java.util.List<String> warnings=new ArrayList<>();protected WorldDocument doInBackground()throws Exception{var result=DocumentStore.load(target);try(var files=Files.list(target.getParent())){for(Path p:files.filter(f->f.toString().endsWith(".sgmap")).limit(64).toList())try{var d=DocumentStore.load(p);if(known.put(d.id(),d)!=null)warnings.add("ID de mapa duplicado: "+d.id());}catch(Exception error){warnings.add(p.getFileName()+": "+error.getMessage());}}return result;}protected void done(){busy=false;ui.setEnabled(true);try{var d=get();ui.document=ui.history.reset(d);ui.canvas.selected.clear();ui.knownMaps.putAll(known);saved=d;file=backup?null:target;ui.layerTools.refresh();ui.warmImages();ui.canvas.repaint();ui.details.setText(String.join("\n",warnings));ui.adminMaps.refresh();ui.liveTools.restart();ui.status.setText(backup?"Backup aberto; use Salvar como para preservar o arquivo original":"Mapa aberto: "+target);}catch(Exception error){ui.error(error);}}}.execute();}
    void create(){JPanel panel=new JPanel(new GridLayout(0,2));JTextField id=new JTextField("novo_mapa"),name=new JTextField("Novo mapa");JSpinner width=new JSpinner(new SpinnerNumberModel(960,32,8192,32)),height=new JSpinner(new SpinnerNumberModel(640,32,8192,32)),grid=new JSpinner(new SpinnerNumberModel(32,1,256,1));JComboBox<String> region=new JComboBox<>(ui.inGameEditor==null?new String[]{"village","forest","ruins"}:new String[]{"forest","village"});if(ui.inGameEditor!=null)region.setSelectedItem(ui.inGameEditor.client.region());id.setToolTipText("ID: letras minusculas, numeros, _ e -; comece por uma letra");for(var row:new Object[][]{{"ID",id},{"Nome",name},{"Largura",width},{"Altura",height},{"Grade",grid},{"Regiao de conteudo",region}}){panel.add(new JLabel((String)row[0]));panel.add((Component)row[1]);}if(JOptionPane.showConfirmDialog(ui,panel,"Novo mapa",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(!WorldDocument.validId(id.getText().strip()))throw new IllegalArgumentException("ID invalido: use letras minusculas, numeros, _ ou -, iniciando por uma letra");var d=WorldDocument.empty(id.getText().strip(),(Integer)width.getValue(),(Integer)height.getValue());d=new WorldDocument(1,d.id(),name.getText(),(String)region.getSelectedItem(),d.width(),d.height(),(Integer)grid.getValue(),d.layers(),d.elements(),d.hitboxes(),d.portals(),d.triggers(),d.metadata());if(ui.maps().containsKey(d.id()))throw new IllegalArgumentException("J? existe um mapa com esse ID");
        ui.knownMaps.put(ui.document.id(),ui.document);d=playable(d);if(ui.inGameEditor!=null){var previous=ui.inGameEditor.target.revision().bundle().maps().values().stream().filter(m->m.region().equals(region.getSelectedItem())).findFirst().orElseThrow();final String nextId=d.id();d=d.withPortals(previous.portals().stream().map(p->new WorldDocument.Portal(p.id(),p.x(),p.y(),p.destination().equals(previous.id())?nextId:p.destination(),p.arrivalX(),p.arrivalY(),p.quest(),p.direction())).toList());}ui.openDocument(d,null);saved=null;ui.adminMaps.refresh();}
    /** Novo cen?rio vazio com ponto de entrada para testar imediatamente no runtime real. */
    static WorldDocument playable(WorldDocument d){
        int x=d.width()/2,y=d.height()/2;int w=Math.min(32,d.width()-x),h=Math.min(32,d.height()-y);
        var spawn=new WorldDocument.Element("editor_spawn",WorldDocument.Kind.PLAYER,"","",new WorldDocument.Crop(0,0,32,32),x,y,w,h,"interaction",true,false,"","FRONT",Map.of());
        return d.withElements(java.util.List.of(spawn));
    }
    void saveCategories(){var catalog=ui.catalog;Path path=ui.project.resolve("studio-projects/catalog.properties");new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{Files.createDirectories(path.getParent());Properties p=new Properties();for(var a:catalog.assets())p.setProperty(a.id(),a.category());try(var out=Files.newBufferedWriter(path)){p.store(out,"Categorias locais; PNGs originais preservados");}return null;}protected void done(){try{get();}catch(Exception error){ui.error(error);}}}.execute();}
}
